"""
Fill one bid position in a web form from calculated values: the mechanical part of the bid worker.

The model reads the form, says which position is on screen and which control takes which value (by the control's
label as its view shows it); `fill_position` then sets the controls in that order. Choices that narrow each other
(select one level, confirm, the next level's options appear) get the confirm button the model named after every
level. Options are matched by value, never by their place in the list, so text-sorted lists ("10, 125, 14, 8") and
look-alike neighbours ("63", "64") do not matter. Nothing here knows a site, a label or a value.

Forms differ: native selects, ARIA comboboxes and listboxes and radio groups are all choices; a page may list
several positions (a table row or a card each), and then every control is taken from the position's own row; the
decimal mark follows the brief (FillPlan.decimal), and a number-only field always takes a decimal point.
"""
import asyncio
import re
from dataclasses import dataclass, field
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

from extract import locate

ZERO_WIDTH = re.compile("[\u200b\u200c\u200d\u2060\ufeff\u00ad]")
CONTROL = re.compile(r'\[(e\d+) (select|combobox|listbox|radiogroup|textbox|textarea|button|checkbox|radio) '
                     r'"((?:[^"\\]|\\.)*)"')
FIELD_KINDS = ("select", "combobox", "listbox", "radiogroup", "textbox", "textarea")  # controls that take a value
CHOICE_KINDS = ("select", "combobox", "listbox", "radiogroup")
NUMBER_OPTION = re.compile(r"^\s*([+-]?\d[\d.,]*)\s*[^\d]*$")

# Values of a bid position: the answer fields from calc plus the material's attributes (keys of `attributes`).
MONEY_KEYS = {"unit_price", "base_unit_price", "surcharge_per_unit", "packaging_per_unit", "rebate_total"}
COUNT_KEYS = {"quantity", "lead_time_weeks"}
REQUIRED_KEYS = ("position", "material_number", "quantity", "unit_price", "lead_time_weeks")
# the material attributes the form's choices lead through (orchestrator.material_attributes gives these names)
ATTRIBUTE_KEYS = ("catalog_group", "bore", "stroke", "pressure", "mounting", "certification")
# every value name a position control can take, known before any value is calculated
VALUE_NAMES = (*REQUIRED_KEYS[1:], "base_unit_price", "surcharge_per_unit", "packaging_per_unit", "rebate_total",
               *ATTRIBUTE_KEYS)


def clean(text: str) -> str:
    return " ".join(ZERO_WIDTH.sub("", text or "").split()).casefold()


def parse_number(text: str) -> Decimal | None:
    """A number written the German way ("1.234,5"), the English way ("1,234.5") or plain; None if it is none."""
    t = ZERO_WIDTH.sub("", text or "").strip().replace(" ", "").replace("\u202f", "").replace("\u00a0", "")
    if not re.fullmatch(r"[+-]?\d[\d.,]*", t):
        return None
    if "," in t and "." in t:  # the later separator is the decimal one
        t = t.replace(".", "").replace(",", ".") if t.rfind(",") > t.rfind(".") else t.replace(",", "")
    elif "," in t:  # one comma is a decimal comma (German), several are thousands separators
        t = t.replace(",", ".") if t.count(",") == 1 else t.replace(",", "")
    elif t.count(".") > 1:
        t = t.replace(".", "")
    try:
        return Decimal(t)
    except InvalidOperation:
        return None


def german(value, places: int = 2, mark: str = ",") -> str:
    """A number without thousands separators, decimal comma by default: 1234.5 -> "1234,50", places=0 -> "1235"."""
    number = Decimal(str(value)).quantize(Decimal(1).scaleb(-places), rounding=ROUND_HALF_UP)
    return f"{number:.{places}f}".replace(".", mark)


def form_value(key: str, value, mark: str = ",") -> str:
    """The text a form field takes for a position value: money with two decimals, counts as integers."""
    if key in MONEY_KEYS:
        return german(value, 2, mark)
    if key in COUNT_KEYS:
        return german(value, 0, mark)
    return str(value)


def number_in(text: str) -> Decimal | None:
    """The number a field shows, also with a unit or currency around it ("2,50 EUR", "3 Wochen"); None without."""
    t = ZERO_WIDTH.sub("", text or "").replace("\u00a0", "").replace("\u202f", "")
    found = re.search(r"[+-]?\d[\d.,]*", t.replace(" ", ""))
    return parse_number(found.group(0).rstrip(".,")) if found else None


# what a brief may say about the number format of the form; explicit words win over example numbers
COMMA_WORDS = re.compile(r"dezimalkomma|decimal comma|komma als dezimal|comma as (?:the )?decimal|"
                         r"deutsche[nms]? (?:zahlen)?format|german (?:number )?format")
POINT_WORDS = re.compile(r"dezimalpunkt|decimal point|decimal dot|punkt als dezimal|point as (?:the )?decimal|"
                         r"dot as (?:the )?decimal|english (?:number )?format")
COMMA_EXAMPLE = re.compile(r"(?<![\d,.])\d+,\d{2}(?!\d|[.,]\d)")
POINT_EXAMPLE = re.compile(r"(?<![\d,.])\d+\.\d{2}(?!\d|[.,]\d)")


def decimal_mark(text: str) -> str:
    """
    The decimal mark the brief's submission steps ask for: "." or ",". Stated words first, then the example
    amounts it writes (only when all of them agree); a decimal comma (the German default) when it says nothing.
    """
    t = clean(text)
    comma, point = bool(COMMA_WORDS.search(t)), bool(POINT_WORDS.search(t))
    if comma != point:
        return "," if comma else "."
    comma, point = bool(COMMA_EXAMPLE.search(t)), bool(POINT_EXAMPLE.search(t))
    return "." if point and not comma else ","


def same_number(shown: str, wanted: str) -> bool:
    """Whether a field shows the number we entered, whatever its notation ("2.5" for "2,50")."""
    a, b = number_in(shown), number_in(wanted)
    return a is not None and a == b


def match_option(options: list[dict], wanted: str) -> tuple[dict | None, str]:
    """
    The one option of a select that means `wanted`, or None and why.

    Tried in order, each must give exactly one option: the same text or value; the same number (an option that is
    a number plus a unit, "3 Wochen" for 3); `wanted` as a whole token of the option text (a catalogue number
    followed by details). Placeholder options (empty value) never match.
    """
    real = [o for o in options if (o.get("value") or "").strip() and not o.get("disabled")]
    want = clean(wanted)
    if not want:
        return None, "no value to choose"
    exact = [o for o in real if clean(o["text"]) == want or clean(o["value"]) == want]
    if len(exact) == 1:
        return exact[0], ""
    number = parse_number(wanted.split()[0]) if wanted.split() else None
    if number is not None and NUMBER_OPTION.match(wanted):
        same = []
        for o in real:
            m = NUMBER_OPTION.match(ZERO_WIDTH.sub("", o["text"]))
            if m and parse_number(m.group(1)) == number:
                same.append(o)
        if len(same) == 1:
            return same[0], ""
        if len(same) > 1:
            return None, f"{len(same)} options equal {wanted!r}"
    token = re.compile(r"(?<![\w-])" + re.escape(want) + r"(?![\w-])")
    hits = [o for o in real if re.search(r"\d", want) and token.search(clean(o["text"]))]
    if len(hits) == 1:
        return hits[0], ""
    if len(hits) > 1:
        return None, f"{len(hits)} options contain {wanted!r}: " + " | ".join(o["text"] for o in hits[:8])
    return None, f"no option means {wanted!r}"


def controls(view: str) -> list[tuple[str, str, str]]:
    """(ref, kind, label) of every form control in a view, in page order."""
    return [(ref, kind, label.replace('\\"', '"')) for ref, kind, label in CONTROL.findall(view)]


def find_control(view: str, label: str, kinds: tuple[str, ...] = ()) -> tuple[str | None, str]:
    """The ref of the control whose label is `label` (exactly, else the one label that contains it)."""
    want = clean(label)
    found = [(ref, kind, text) for ref, kind, text in controls(view) if not kinds or kind in kinds]
    exact = [c for c in found if clean(c[2]) == want]
    if exact:
        return exact[0][0], ""
    partial = [c for c in found if want and want in clean(c[2])]
    if len(partial) == 1:
        return partial[0][0], ""
    if partial:
        return None, f"{label!r} matches several controls: " + ", ".join(repr(c[2]) for c in partial[:6])
    return None, f"no control labelled {label!r} on the page"


def mapping_problems(view: str, fields: dict[str, str], known: set[str], buttons: tuple[str, ...] = ()) -> list[str]:
    """
    What is wrong with a control mapping (label -> value name) for the form in `view`: unknown value names, labels
    that name no control (or several), required values left unmapped, buttons not on the page. [] when usable.
    """
    problems = []
    unknown = sorted({name for name in fields.values() if name not in known})
    if unknown:
        problems.append(f"unknown value names {unknown}; use only: {', '.join(sorted(known))}")
    for label in fields:
        ref, why = find_control(view, label, FIELD_KINDS)
        if ref is None:
            problems.append(why)
    unmapped = sorted(set(REQUIRED_KEYS[1:]) - set(fields.values()))
    if unmapped:
        problems.append(f"no control mapped for {', '.join(unmapped)}")
    for button in filter(None, buttons):
        ref, why = find_control(view, button, ("button",))
        if ref is None:
            problems.append(why)
    return problems


ELEMENT = re.compile(r"\[e\d+ (?:[^\[\]]|\[[^\[\]]*\])*\]")  # one [eN ...] element of a view
FIELD_LINE = re.compile(r"\[e\d+ (?:" + "|".join(FIELD_KINDS) + ") ")


def position_on_page(view: str, position: str) -> bool:
    """
    Whether the page is about this position: its number, as a whole token (01.04 is not 01.041 or 101.04), in a
    heading, in the text above the first choice or field (not among the options further down), or as the text of
    a line that holds fields of its own (a table row or card per position; not a list of positions elsewhere).
    """
    view = ZERO_WIDTH.sub("", view)
    first = re.search(r"\[e\d+ (select|combobox|listbox|radiogroup|textarea|checkbox|radio) ", view)
    head = view[:first.start()] if first else view
    head += "\n" + "\n".join(line for line in view.splitlines() if line.startswith("#"))
    head += "\n" + "\n".join(ELEMENT.sub(" ", line) for line in view.splitlines() if FIELD_LINE.search(line))
    return re.search(r"(?<![\w.])" + re.escape(position.strip()) + r"(?![\w]|\.\d)", head) is not None


def unmapped(view: str, entry: dict, fields: dict[str, str]) -> tuple[list[str], list[str]]:
    """
    Answer values of `entry` that no control is mapped to, and the labels of the page's fields (text boxes, lists)
    that no mapping names. Both non-empty means the model probably skipped part of the form (a live run left every
    price breakdown field empty that way).
    """
    mapped = {clean(label) for label in fields}
    names = set(fields.values())
    values = sorted(k for k in entry if k in MONEY_KEYS | COUNT_KEYS | {"material_number"} and k not in names)
    labels = [label for _, kind, label in controls(view)
              if kind in FIELD_KINDS and clean(label) not in mapped]
    return values, labels


def resolve_position(given: str, numbers, view: str) -> tuple[str | None, list[str]]:
    """
    Which of the bid's position `numbers` to enter now, and the bid's positions the page shows. The page decides:
    forms show positions in their own order, and a model that expects the bid's order names the next position of
    its list while the page shows another one (live runs omitted correct positions that way). So: the position
    `given` names (also inside a longer label such as "Position 01.04") when the page shows it, else the one bid
    position the page shows, else `given` itself if it is a bid position (the caller reports it is not on the page),
    else None (the page shows none of the bid's positions, or several).
    """
    numbers = [str(n).strip() for n in numbers]
    shown = [n for n in numbers if position_on_page(view, n)]
    given = ZERO_WIDTH.sub("", given or "").strip()
    named = [given] if given in numbers else [
        n for n in numbers if re.search(r"(?<![\w.])" + re.escape(n) + r"(?![\w]|\.\d)", given)]
    if len(named) == 1 and named[0] in shown:
        return named[0], shown
    if len(shown) == 1:
        return shown[0], shown
    if len(named) == 1 and not shown:
        return named[0], shown
    return None, shown


def complete_positions(answer: dict, attributes: dict[str, dict[str, str]] | None = None) -> dict[str, dict]:
    """
    The positions that can be entered, by position number: every required answer field present and, for the
    choices that lead to the material, the material's attributes. Others are left out (omitted in the form).
    """
    if not answer or answer.get("decision") != "bid":
        return {}
    attributes = attributes or {}
    entries = {}
    for pos in answer.get("positions", []):
        if any(pos.get(k) in (None, "") for k in REQUIRED_KEYS):
            continue
        entry = {k: v for k, v in pos.items() if v is not None}
        for key, value in (attributes.get(str(pos["position"])) or {}).items():
            entry.setdefault(key, value)
        entries[str(pos["position"]).strip()] = entry
    return entries


@dataclass
class FillPlan:
    """
    What the model said about the form: control label -> value key, the button that confirms a choice, and the
    decimal mark the brief asks for (number-only fields take a decimal point whatever it says).
    """

    fields: dict[str, str] = field(default_factory=dict)
    confirm: str = ""
    decimal: str = ","


NUMBER_ONLY = "A number must match exactly: leave this position out."  # a value failure, not a form problem

KIND_JS = """e => {
  const role = e.getAttribute('role');
  if (e.tagName === 'SELECT') return 'select';
  if (role === 'listbox') return 'listbox';
  if (role === 'radiogroup' || e.tagName === 'FIELDSET') return 'radiogroup';
  if (role === 'combobox') return e.tagName === 'INPUT' ? 'typeahead' : 'combobox';
  if (e.tagName === 'INPUT' && (e.type || '').toLowerCase() === 'number') return 'number';
  return 'text';
}"""
DISABLED_JS = "e => !!(e.disabled || e.readOnly === true || e.getAttribute('aria-disabled') === 'true')"
SHOWN_JS = "e => ('value' in e && typeof e.value === 'string') ? e.value : (e.innerText || '')"

# The options of a choice that is not a native select (radio group, listbox, opened combobox), each tagged with a
# ref of its own so it can be clicked like a person would.
OPTIONS_JS = r"""(e, base) => {
  const clean = s => (s || '').replace(/[​‌‍⁠﻿­]/g, '').replace(/\s+/g, ' ').trim();
  const doc = e.ownerDocument, win = doc.defaultView;
  const shown = o => {
    if (o.hidden || o.getAttribute('aria-hidden') === 'true') return false;
    const cs = win.getComputedStyle(o);
    return cs.display !== 'none' && cs.visibility !== 'hidden';
  };
  const label = o => {
    if (o.getAttribute('aria-label')) return clean(o.getAttribute('aria-label'));
    if (o.labels && o.labels.length) return clean(Array.from(o.labels).map(l => l.textContent).join(' '));
    return clean(o.innerText || o.textContent || o.value || '');
  };
  const role = e.getAttribute('role');
  let items, on;
  if (role === 'radiogroup' || e.tagName === 'FIELDSET') {
    items = Array.from(e.querySelectorAll('input[type=radio], [role=radio]'));
    on = o => o.checked === true || o.getAttribute('aria-checked') === 'true';
  } else {
    on = o => o.getAttribute('aria-selected') === 'true';
    if (role === 'listbox') items = Array.from(e.querySelectorAll('[role=option]'));
    else {  // a combobox: its popup, else the options of a list that no other control owns
      const ids = (e.getAttribute('aria-controls') || e.getAttribute('aria-owns') || '').split(/\s+/).filter(Boolean);
      const pops = ids.map(id => doc.getElementById(id)).filter(Boolean);
      items = pops.flatMap(p => Array.from(p.querySelectorAll('[role=option]')));
      if (!items.length) {
        const all = Array.from(doc.querySelectorAll('[role=option]')).filter(shown);
        const free = all.filter(o => {
          const box = o.closest('[role=listbox]');
          return !box || !box.hasAttribute('data-ar');
        });
        items = free.length ? free : all;
      }
    }
  }
  return items.filter(o => shown(o) || (o.tagName === 'INPUT' && o.labels && o.labels.length)).map((o, i) => {
    const ref = base + 'o' + i;
    o.setAttribute('data-ar', ref);
    const text = label(o);
    const value = o.tagName === 'INPUT' ? (o.value && o.value !== 'on' ? o.value : text)
                                         : (o.getAttribute('data-value') || o.getAttribute('value') || text);
    return {ref, text, value, selected: on(o), radio: o.tagName === 'INPUT',
            disabled: !!(o.disabled || o.getAttribute('aria-disabled') === 'true')};
  });
}"""

# Several positions on one page (a table row or a card each): the control at the same place in the row or card
# that shows `position`. Kept as it is when the page has no such row, or when the control already sits in it.
SCOPE_JS = r"""(el, pos) => {
  const ZW = /[​‌‍⁠﻿­]/g;
  const doc = el.ownerDocument;
  const esc = pos.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp('(^|[^\\w.])' + esc + '(?![\\w]|\\.\\d)');
  const FIELDS = 'input:not([type=hidden]),select,textarea,[role=combobox],[role=listbox],[role=radiogroup]';
  const keep = {ref: null, inside: true};
  const walker = doc.createTreeWalker(doc.body, NodeFilter.SHOW_TEXT);
  const found = [];
  for (let t = walker.nextNode(); t; t = walker.nextNode()) {
    let a = t.parentElement;
    if (!a || !re.test(t.nodeValue.replace(ZW, ''))) continue;
    if (a.closest('select,option,script,style,[role=option],[hidden],[aria-hidden=true]')) continue;
    if (!a.getClientRects().length) continue;
    while (a && a !== doc.body && !a.querySelector(FIELDS)) a = a.parentElement;
    if (a && a !== doc.body) found.push(a);
  }
  if (!found.length) return keep;
  const count = c => c.querySelectorAll(FIELDS).length;
  found.sort((x, y) => count(x) - count(y));
  const box = found[0];
  if (box.contains(el)) return keep;
  // the row of the control and the row of the position: children of their closest common ancestor
  let mine = el;
  const path = [];
  while (mine.parentElement && !mine.parentElement.contains(box)) {
    path.unshift(Array.from(mine.parentElement.children).indexOf(mine));
    mine = mine.parentElement;
  }
  const common = mine.parentElement;
  if (!common) return {ref: null, inside: false};
  let row = box;
  while (row.parentElement !== common) row = row.parentElement;
  const shape = c => Array.from(c.querySelectorAll(FIELDS))
    .map(f => f.tagName + (f.type || '') + (f.getAttribute('role') || '')).join(',');
  if (row.tagName !== mine.tagName || shape(row) !== shape(mine)) return {ref: null, inside: false};
  let x = row;
  for (const i of path) x = x && x.children[i];
  if (!x || x.tagName !== el.tagName || (x.type || '') !== (el.type || '')) return {ref: null, inside: false};
  const ref = 'es' + Math.random().toString(36).slice(2, 10);
  x.setAttribute('data-ar', ref);
  return {ref, inside: true};
}"""


async def _select_state(element) -> dict:
    return await element.evaluate(
        "e => ({disabled: e.disabled, options: Array.from(e.options).map(o => ({value: o.value, "
        "text: (o.textContent || '').trim(), selected: o.selected, disabled: o.disabled}))})")


async def scoped(session, element, position: str):
    """`element`, or the control at the same place in the row or card of `position`; and whether it is in there."""
    if element is None or not position:
        return element, True
    try:
        found = await element.evaluate(SCOPE_JS, position)
    except Exception:
        return element, True
    if found.get("ref"):
        other = await locate(session.page, found["ref"])
        if other is not None:
            return other, True
    return element, bool(found.get("inside", True))


async def _ref(element) -> str:
    return (await element.get_attribute("data-ar")) or "ex"


async def choice_options(element, kind: str) -> list[dict]:
    """The options of a choice control, opening a closed combobox first."""
    if kind == "select":
        return (await _select_state(element))["options"]
    if kind == "combobox" and await element.get_attribute("aria-expanded") != "true":
        await element.click(timeout=5000)
        await asyncio.sleep(0.3)
    return await element.evaluate(OPTIONS_JS, await _ref(element))


async def pick_option(session, element, kind: str, option: dict) -> None:
    """Choose `option` (from choice_options) the way a person would: select it, tick its radio or click it."""
    if kind == "select":
        await element.select_option(value=option["value"], timeout=5000)
        return
    target = await locate(session.page, option["ref"])
    if target is None:
        raise LookupError(f"option {option['text']!r} vanished")
    if option.get("radio"):
        try:
            await target.check(timeout=3000)
        except Exception:  # a styled radio hides its input: its label takes the click
            await target.evaluate("e => (e.labels && e.labels[0] ? e.labels[0] : e).click()")
    else:
        await target.click(timeout=5000)
    await asyncio.sleep(0.15)


async def holds_option(element, kind: str, option: dict) -> bool:
    """Whether the choice control shows `option` as chosen."""
    if kind == "select":
        return await element.evaluate("e => e.value") == option["value"]
    if kind == "combobox":
        shown = clean(await element.evaluate(SHOWN_JS))
        if shown and clean(option["text"]) in shown:
            return True
    options = await element.evaluate(OPTIONS_JS, await _ref(element))
    return any(o["selected"] and clean(o["text"]) == clean(option["text"]) for o in options)


def choice_hint(view: str, plan: FillPlan, picked: dict[str, str], entry: dict) -> str:
    """
    The page's choices that no value is mapped to (a series or group that narrows the next list), with their
    options, for the model to pick through `choices`; '' when there are none.
    """
    mapped = {clean(label) for label in plan.fields} | set(picked)
    lines = []
    for element in ELEMENT.findall(view):
        found = CONTROL.match(element)
        if not found or found.group(2) not in CHOICE_KINDS or clean(found.group(3)) in mapped:
            continue
        options = element.split(" options: ", 1)[1].rstrip("]") if " options: " in element else ""
        lines.append(f"{found.group(3)!r}" + (f" (options: {options[:300]})" if options else ""))
    if not lines:
        return ""
    answer_keys = MONEY_KEYS | COUNT_KEYS | {"material_number", "position"}
    wanted = ", ".join(f"{k} {v}" for k, v in entry.items() if k not in answer_keys)
    return (f" No value is mapped to these choices of the page: {'; '.join(lines)}. If one of them must be set "
            f"first, call again with choices={{label: the option that fits this position"
            f"{f' ({wanted})' if wanted else ''}}}.")


async def _confirm(session, plan: FillPlan, view: str, position: str = "") -> tuple[str, str | None]:
    """Click the button the model named as the confirm of a choice; the new view, or the old one and an error."""
    button, why = find_control(view, plan.confirm, ("button",))
    target = await locate(session.page, button) if button else None
    target, _ = await scoped(session, target, position)
    if target is None:
        return view, why or f"{plan.confirm!r} vanished from the page"
    await target.click(timeout=5000)
    await session.settle()
    return await session.look(), None


async def fill_position(session, entry: dict, plan: FillPlan, log: list[str],
                        choices: dict[str, str] | None = None) -> str | None:
    """
    Enter one position's values into the form on screen, control by control in page order; returns an error
    message, or None when every mapped control holds its value.

    A choice (select, combobox, listbox, radio group) mapped to a material attribute (a key that is not an answer
    field) narrows the next one: after setting it, `plan.confirm` is clicked so the page offers the next level, and
    the choice must survive that round trip. A control still disabled (a choice from an earlier visit not yet
    confirmed) gets one confirm. `choices` (label -> option text) is the model's pick for such a choice, used where
    a worded attribute matches no option literally, and for choices no value is mapped to (a series the cascade
    needs); numbers must match exactly, and answer fields are never overridden. On a page with several positions,
    every control comes from the row or card of this position.
    """
    picked = {clean(label): text for label, text in (choices or {}).items()}
    answer_keys = MONEY_KEYS | COUNT_KEYS | {"material_number", "position"}
    # a position counts as entered only with its material, quantity, price and lead time (the material control
    # opens only once the choices before it are made)
    missing = sorted(set(REQUIRED_KEYS) - {"position"} - set(plan.fields.values()))
    if missing:
        return f"no control mapped for {', '.join(missing)}: add them to fields"
    position = str(entry.get("position") or "").strip()
    view = await session.look()
    order = {clean(label): i for i, (_, _, label) in enumerate(controls(view))}
    mapped = {clean(label) for label in plan.fields}
    steps: list[tuple[str, str | None]] = list(plan.fields.items())
    steps += [(label, None) for label in (choices or {}) if clean(label) not in mapped]
    steps.sort(key=lambda item: order.get(clean(item[0]), len(order)))
    for label, key in steps:
        if key is not None and key not in entry:
            log.append(f"{label}: left empty (this bid gives no value for it, which is fine)")
            continue
        value = form_value(key, entry[key], plan.decimal) if key else picked[clean(label)]
        element = None
        for attempt in range(2):
            ref, why = find_control(view, label, FIELD_KINDS)
            element = await locate(session.page, ref) if ref else None
            if element is None and ref is None and key not in REQUIRED_KEYS:
                # a label the model guessed for a value the form has no control for (live: "Druck" for the
                # pressure, which the form shows only inside the catalogue option): skip it, never fail the
                # position over it; the required values still need their controls
                break
            if element is None:
                return why or f"{label!r} vanished from the page"
            element, _ = await scoped(session, element, position)
            if not await element.evaluate(DISABLED_JS):
                break
            if attempt or not plan.confirm:
                return (f"{label!r} is disabled: an earlier choice was not confirmed or leads elsewhere "
                        f"(check the values chosen so far).{choice_hint(view, plan, picked, entry)}")
            # a choice made on an earlier visit may still wait for its confirm
            view, error = await _confirm(session, plan, view, position)
            if error:
                return error
        if element is None:
            log.append(f"{label}: no such control on this page; skipped")
            continue
        kind = await element.evaluate(KIND_JS)
        if kind in CHOICE_KINDS:
            options = await choice_options(element, kind)
            option, why = match_option(options, value)
            if (option is None and key is not None and key not in answer_keys and clean(label) in picked
                    and parse_number(value) is None):
                option, why = match_option(options, picked[clean(label)])  # the model's reading
            if option is None:
                if kind == "combobox":
                    await element.press("Escape")
                shown = " | ".join(o["text"] for o in options if o["value"])[:600]
                worded = key is not None and key not in answer_keys and parse_number(value) is None
                if worded:
                    hint = (f" If one option means the same as {value!r}, call again with choices={{{label!r}: "
                            f"<that option>}}.")
                else:  # a list narrowed by a choice nobody made yet, else a value the form does not offer
                    hint = choice_hint(view, plan, picked, entry) or " " + NUMBER_ONLY
                return f"{label!r}: {why}. Options: {shown}.{hint}"
            changed = not option.get("selected")
            if changed:
                await pick_option(session, element, kind, option)
                if not await holds_option(element, kind, option):
                    return f"{label!r} did not take {option['text']!r}"
            elif kind == "combobox":
                await element.press("Escape")
            log.append(f"{label} = {option['text']}")
            if key in answer_keys or not plan.confirm or not changed:
                continue
            view, error = await _confirm(session, plan, view, position)
            if error:
                return error
            ref, _ = find_control(view, label, CHOICE_KINDS)
            kept = await locate(session.page, ref) if ref else None
            kept, _ = await scoped(session, kept, position)
            if kept is None or not await holds_option(kept, kind, option):
                return f"{label!r} lost its choice after {plan.confirm!r}"
        else:
            numeric = key in MONEY_KEYS | COUNT_KEYS
            if kind == "number" and numeric:  # a number-only field takes a decimal point
                value = form_value(key, entry[key], ".")
            await element.fill(value, timeout=5000)
            if kind == "typeahead":  # a field that suggests options: take the one that means the value
                await asyncio.sleep(0.3)
                option, _ = match_option(await element.evaluate(OPTIONS_JS, await _ref(element)), value)
                if option is not None:
                    await pick_option(session, element, "combobox", option)
            shown = await element.evaluate(SHOWN_JS)
            if not (same_number(shown, value) if numeric else clean(value) in clean(shown)):
                return f"{label!r} did not take {value!r} (it shows {shown!r})"
            log.append(f"{label} = {value}")
    return None

"""
One website in one tab, and the actions a model may take on it.

`SiteSession` owns the tab (and popups it opens) for one website. After every action it settles the page with
generic helpers that make no decisions: sign in with the run's credentials when a login form shows, accept only
the necessary cookies, pass "slide to unlock / not a robot" checks, close modal popups through their close button,
reload transient error pages and sign in again after a session timeout. What to open, search, read and enter is
left to the model through `TOOLS`.
"""
import asyncio
import contextvars
import os
import re
import time
from dataclasses import dataclass, field
from urllib.parse import urljoin, urlparse

from extract import FRAME_SECONDS, changes, locate, observe, select_options
from playwright.async_api import BrowserContext, Dialog, Page
from pydantic_ai import RunContext
from tracing import Trace

SETTLE_SECONDS = 45  # upper bound for waiting on a page and its helpers after one action
MAX_VIEW = 14000  # characters of a page shown at once; read_more pages through the rest
# A start waits on its tab while it loads: a slow site under load is still alive, and a new tab only queues behind
# the old request. But a tab can also hang for minutes in a context whose requests never complete while the same
# site opens at once in a fresh context (seen in sandbox runs). So an attempt without a usable page after RACE_AFTER
# gets a second tab in a fresh context next to it; the first usable page wins and the other tab is closed.
ATTEMPT_SECONDS = (45, 60, 90, 120)  # budgets of successive attempts (the last repeats)
START_SECONDS = float(os.environ.get("SESSION_START_SECONDS", "120"))  # no attempt runs longer than this
RACE_AFTER = 15  # an attempt without a usable page this long races a tab in a fresh context against its own
STUCK_SECONDS = 20  # a loaded page that answers no script call this long is dead: its tab is given up
PROBE_SECONDS = 5  # one check whether the page answers a script call
HELPER_SECONDS = 15  # one settle helper (sign-in, cookies, ...) on one page
GOTO_SECONDS = 30  # a navigation may take this long before the page is waited on in smaller steps
SLOW_PAGE = 10  # a navigation slower than this is traced
LOOK_SECONDS = 30  # one try to read a page that is still loading during a start
LOGIN_PATIENCE = 45  # a sign-in form still showing this soon after sending it is the post still pending
START_BACKOFF = (0, 10, 30)  # seconds between failed attempts (the last repeats); retries use a fresh context
START_MARGIN = 300  # by default a start keeps retrying until this long before the run's deadline
MIN_ATTEMPT = 15  # an attempt (or a racing tab) with less time than this is not begun
FRESH_AFTER = 1  # after this many failed attempts, each one runs in a fresh browser context (rules out the context)
DEADLINE: float | None = None  # the run's deadline (time.monotonic()); agent.solve sets it
_STARTING: contextvars.ContextVar = contextvars.ContextVar("starting", default=None)  # the session start() runs for
LOOP_VISITS = 3  # arriving on one page this often in a session gets the model a loop hint

# Closes modal <dialog>s and aria-modal popups through their own close button as soon as they open, and records
# what it closed. Links inside popups ("accept and continue") are never followed.
AUTO_CLOSE_JS = r"""
(() => {
  if (window.__arInit) return;
  window.__arInit = true;
  const CLOSE = /^(×|✕|✖|x|schließen|schliessen|close|dismiss|ausblenden|später|later|nicht jetzt|not now)$/i;
  const closed = (window.__arClosed = window.__arClosed || []);
  function closeButton(d) {
    for (const b of d.querySelectorAll('button,[role=button]')) {
      const name = (b.getAttribute('aria-label') || b.textContent || '').trim();
      if (CLOSE.test(name) || b.hasAttribute('data-close')) return b;
    }
    return null;
  }
  function check() {
    for (const d of document.querySelectorAll('dialog[open],[role=dialog][aria-modal=true],[role=alertdialog]')) {
      const modal = d.tagName !== 'DIALOG' || d.matches(':modal');
      if (!modal || d.dataset.arClosed) continue;
      const b = closeButton(d);
      if (!b) continue;
      d.dataset.arClosed = '1';
      closed.push((d.getAttribute('aria-label') || d.querySelector('h1,h2,h3')?.textContent || 'popup').trim());
      b.click();
      if (d.tagName === 'DIALOG' && d.open) d.close();
    }
  }
  const start = () => {
    check();
    new MutationObserver(check).observe(document.documentElement,
      {subtree: true, childList: true, attributes: true, attributeFilter: ['open', 'aria-modal', 'style', 'class']});
  };
  if (document.documentElement) start(); else document.addEventListener('DOMContentLoaded', start);
})();
"""

# "Slide to unlock" plus "I am not a robot" checks in any frame: drag the slider to its end, tick only boxes that
# are labelled as a robot check. Other checkboxes (terms, declarations) are left to the model.
HUMAN_CHECK_JS = r"""
() => {
  const ROBOT = /roboter|robot|mensch\b|human/i, SLIDE = /entsperr|unlock|zieh|slide|schieb/i;
  const labels = e => e.labels ? Array.from(e.labels).map(l => l.textContent) : [];
  const text = e => [e.getAttribute('aria-label') || '', ...labels(e)].join(' ');
  const done = [];
  for (const r of document.querySelectorAll('input[type=range]')) {
    const around = text(r) + ' ' + (r.parentElement ? r.parentElement.textContent : '');
    const max = r.max || '100';
    if (!SLIDE.test(around) || r.value === max || r.disabled) continue;
    r.value = max;
    r.dispatchEvent(new Event('input', {bubbles: true}));
    r.dispatchEvent(new Event('change', {bubbles: true}));
    done.push('unlock slider');
  }
  for (const c of document.querySelectorAll('input[type=checkbox]')) {
    if (c.checked || c.disabled || !ROBOT.test(text(c))) continue;
    c.click();
    done.push('robot check');
  }
  return done;
}
"""

ERROR_PAGE = re.compile(r"vorübergehend nicht verfügbar|temporarily unavailable|service unavailable|bad gateway|"
                        r"gateway time-?out|internal server error|bitte versuchen sie es (später )?erneut",
                        re.IGNORECASE)
COOKIE = re.compile(r"cookie", re.IGNORECASE)
COOKIE_ANSWER = re.compile(r"akzeptier|accept|zustimm|agree|ablehn|reject|erlaub|allow|bestätig|confirm|ok\b",
                           re.IGNORECASE)
COOKIE_MINIMAL = re.compile(r"notwendig|erforderlich|necessary|essential|nur technisch|ablehnen|reject|decline",
                            re.IGNORECASE)


def _budget(attempt: int) -> float:
    """Seconds start attempt `attempt` (from 1) may take."""
    return min(START_SECONDS, ATTEMPT_SECONDS[min(attempt, len(ATTEMPT_SECONDS)) - 1])


async def _close_quietly(page: Page) -> None:
    try:
        await asyncio.wait_for(page.close(), 10)
    except Exception:
        pass


async def _close_context(context: BrowserContext | None) -> None:
    if context is None:
        return
    try:
        await asyncio.wait_for(context.close(), 10)
    except Exception:
        pass


@dataclass
class SiteSession:
    """A website of the run (`siteId`, `url`, `credentials`) worked in its own tab."""

    site: dict
    context: BrowserContext
    trace: Trace
    pages: list[Page] = field(default_factory=list)
    events: list[str] = field(default_factory=list)  # what the helpers did since the model last looked
    view: str = ""
    lock: asyncio.Lock = field(default_factory=asyncio.Lock)
    stamp: int = 0
    logins: int = 0
    restarts: int = 0  # times the site was started again because its page stopped answering (reopen)
    seen: str = ""  # every view's text this session, to check notes against
    shown: tuple = ()  # (url, title, view) the model has now, so an unchanged page is not sent again
    base: tuple = ()  # the same for the latest view it got in full; changes are told against this one
    visits: dict[str, int] = field(default_factory=dict)  # page URL -> times the model arrived on it
    last_url: str = ""
    scripted: object = None  # the context the popup closer is installed in
    until: float | None = None  # a running start retries until then; may be moved while it runs
    ok: bool = False  # a start succeeded
    settled: asyncio.Event = field(default_factory=asyncio.Event)  # the latest start ended, either way
    login_at: tuple = ()  # (time.monotonic(), url) of the latest sign-in the helpers sent
    _start_owner: object = None  # set while start() runs; its own looks (any task under it) must not wait
    _old_context: object = None
    _adopted_by: object = None  # a start contender whose tab won: the session that took its tab over

    @property
    def name(self) -> str:
        return self.site["siteId"]

    @property
    def page(self) -> Page:
        open_pages = [p for p in self.pages if not p.is_closed()]
        self.pages = open_pages
        return open_pages[-1]

    def default_until(self) -> float:
        if DEADLINE is not None:
            return DEADLINE - START_MARGIN
        return time.monotonic() + _budget(1) + START_BACKOFF[0] + _budget(2)

    @property
    def starting(self) -> bool:
        return self._start_owner is not None

    async def start(self, attempts: int | None = None, until: float | None = None) -> str:
        """
        Open the site's start page in a new tab, signed in. One attempt waits on its tab while the page loads (its
        budget grows with the attempts, ATTEMPT_SECONDS); after RACE_AFTER without a usable page a second tab in a
        fresh context races it, and the first usable page wins. A tab ends early on the browser's error page, when
        it closes, or when its page stops answering (STUCK_SECONDS). Failed attempts are retried in a fresh
        context after a short backoff until `until` (default: START_MARGIN before the run's deadline; `self.until`
        may be moved while this runs) or `attempts` attempts.
        """
        if until is not None or self.until is None:
            self.until = until if until is not None else self.default_until()
        self._start_owner = _STARTING.set(self)
        self.ok = False
        self.settled.clear()
        if self._old_context is None:
            self._old_context = self.context  # the context the session was made with
        began = time.monotonic()
        tries = 0
        try:
            while True:
                tries += 1
                end = min(time.monotonic() + _budget(tries), self.until)
                own = (self.context, self.scripted)
                fresh = await self._fresh_context() if tries > FRESH_AFTER else None
                if fresh is not None:
                    self.context, self.scripted = fresh, None
                try:
                    winner, view = await self._race(end, began)
                except asyncio.CancelledError:
                    await self._close_pages()
                    self.context, self.scripted = own
                    await _close_context(fresh)
                    raise
                except Exception as error:
                    self.trace.event(self.name, "start_failed", attempt=tries,
                                     seconds=round(time.monotonic() - began, 1),
                                     error=f"{type(error).__name__}: {str(error)[:160]}")
                    await self._close_pages()
                    self.context, self.scripted = own  # the fresh context did not help: back
                    await _close_context(fresh)
                else:
                    if winner is not self:
                        await self._adopt(winner)
                        await _close_context(fresh)  # this attempt's own context lost the race
                    self.ok = True
                    self.trace.event(self.name, "start_ok", attempt=tries, seconds=round(time.monotonic() - began, 1),
                                     fresh_context=self.context is not self._old_context, raced=winner is not self)
                    return view
                if attempts is not None and tries >= attempts:
                    break
                wait = START_BACKOFF[min(tries, len(START_BACKOFF)) - 1]
                if time.monotonic() + wait + MIN_ATTEMPT > self.until:
                    break
                self.trace.event(self.name, "start_retry", after=wait, attempt=tries + 1)
                await asyncio.sleep(wait)
            raise TimeoutError(f"{self.name}: the site could not be opened in {tries} attempts "
                               f"({round(time.monotonic() - began)} s)")
        finally:
            _STARTING.reset(self._start_owner)
            self._start_owner = None
            self.settled.set()

    async def _race(self, end: float, began: float) -> tuple["SiteSession", str]:
        """
        One attempt: a tab of this session, and after RACE_AFTER without a usable page a second one next to it, in a
        fresh context and a session of its own (nothing is given up: the first tab may still answer first). Returns
        the session whose tab showed a usable page first, and that page; the racer's tab and context are closed
        unless it won. Raises the last error when every tab failed.
        """
        tasks = {asyncio.create_task(self._attempt(end)): self}
        racer_context = None
        error: BaseException | None = None
        winner = None
        raced_at = time.monotonic() + RACE_AFTER
        try:
            while tasks:
                timeout = (None if racer_context is not None or raced_at == float("inf")
                           else max(0.0, raced_at - time.monotonic()))
                done, _ = await asyncio.wait(tasks, timeout=timeout, return_when=asyncio.FIRST_COMPLETED)
                for task in done:
                    contender = tasks.pop(task)
                    if task.exception() is None:
                        winner = contender
                        return contender, task.result()
                    error = task.exception()
                    if tasks:  # the other tab still runs: this one's failure is only traced
                        self.trace.event(self.name, "start_tab_failed", seconds=round(time.monotonic() - began, 1),
                                         raced=contender is not self,
                                         error=f"{type(error).__name__}: {str(error)[:160]}")
                    if contender is not self:
                        await contender._close_pages()
                if done:
                    continue
                if racer_context is None and end - time.monotonic() > MIN_ATTEMPT:
                    racer_context = await self._fresh_context(why="race")
                    if racer_context is not None:
                        racer = SiteSession(self.site, racer_context, self.trace)
                        racer.stamp = self.stamp
                        tasks[asyncio.create_task(racer._attempt(end))] = racer
                        continue
                raced_at = float("inf")  # no second tab (too little time, no context): wait on the first one
            raise error or TimeoutError("no tab")
        finally:
            for task in tasks:
                task.cancel()
            if tasks:
                await asyncio.wait(list(tasks), timeout=15)  # a cancel of this start itself still propagates
            for contender in tasks.values():
                if contender is not self:
                    await contender._close_pages()
            if racer_context is not None and (winner is None or winner.context is not racer_context):
                await _close_context(racer_context)

    async def _adopt(self, racer: "SiteSession") -> None:
        """Take over the racer's tab, context, sign-in state and view; its tab's handlers now report here."""
        await self._close_pages()
        racer._adopted_by = self
        self.context, self.scripted, self.pages, self.view = racer.context, racer.scripted, racer.pages, racer.view
        self.stamp, self.logins, self.login_at = max(self.stamp, racer.stamp), racer.logins, racer.login_at
        self.events.extend(racer.events)
        self.seen += racer.seen
        self.shown, self.base, self.last_url = racer.shown, racer.base, racer.last_url
        for url, count in racer.visits.items():
            self.visits[url] = self.visits.get(url, 0) + count

    async def _fresh_context(self, why: str = "retry") -> BrowserContext | None:
        """A new context of the same browser, so a broken context (a stuck connection, cookies, a hung tab) is
        ruled out. None when the browser cannot make one."""
        try:
            browser = self.context.browser
            if browser is None:
                return None
            fresh = await asyncio.wait_for(browser.new_context(viewport={"width": 1280, "height": 800}), 20)
        except Exception as error:
            self.trace.event(self.name, "helper_error", helper="fresh_context", error=str(error)[:160])
            return None
        self.trace.event(self.name, "helper", action="fresh_context", why=why)
        return fresh

    async def _close_pages(self) -> None:
        for page in self.pages:
            try:
                await asyncio.wait_for(page.close(), 10)
            except Exception:
                pass
        self.pages = []

    async def _attempt(self, end: float) -> str:
        """One tab of a start attempt: navigate, then settle and look until the page shows, the browser's error
        page shows, the tab closes, its page stops answering script calls, or `end`."""
        if self.scripted is not self.context:
            await self.context.add_init_script(AUTO_CLOSE_JS)
            self.scripted = self.context
        page = await self.context.new_page()
        self._watch(page)
        try:
            await page.goto(self.site["url"], wait_until="domcontentloaded",
                            timeout=max(1.0, min(GOTO_SECONDS, end - time.monotonic())) * 1000)
        except Exception as error:  # still loading: the request is not given up, the tab waits on
            self.trace.event(self.name, "start_wait", phase="goto", url=page.url[:120],
                             error=str(error).splitlines()[0][:120])
        self.logins = 0
        view, phase, silent = "", "goto", None

        def waiting(now: str) -> None:  # traced once per phase, not once per check
            nonlocal phase
            if now != phase:
                self.trace.event(self.name, "start_wait", phase=now, url=self.page.url[:120])
            phase = now

        while True:
            left = end - time.monotonic()
            self._check_alive()
            if left <= 1:
                if view:  # it shows something (a sign-in still pending): better than another tab
                    return view
                raise TimeoutError(f"still loading ({self.page.url[:80]})")
            answer = await self._answers()
            if answer != "yes":  # nothing on the tab answers: a navigation not yet committed, or a hung page
                committed = not self.page.url.startswith("about:")
                if answer == "hung" and committed:
                    silent = silent or time.monotonic() - PROBE_SECONDS
                    if time.monotonic() - silent >= STUCK_SECONDS:
                        raise ConnectionError(f"the page does not respond ({self.page.url[:80]})")
                waiting("respond" if committed else "commit")
                await asyncio.sleep(min(1.0, max(0.0, left - 1)))
                continue
            silent = None
            try:
                await asyncio.wait_for(self._settle(), min(SETTLE_SECONDS, left))
            except asyncio.TimeoutError:  # the page answers but keeps loading: look at what it shows anyway
                waiting("settle")
            self._check_alive()
            try:
                view = await asyncio.wait_for(self.look(), max(1.0, min(LOOK_SECONDS, end - time.monotonic())))
            except asyncio.TimeoutError:
                waiting("look")
                view = ""
                continue
            if not self.view.strip() or self.view.startswith(("(the page does not respond", "(page error")):
                view = ""
                waiting("render")
                await asyncio.sleep(1.0)
                continue
            if await self._login_pending():
                waiting("login")
                await asyncio.sleep(2.0)
                continue
            return view

    async def _answers(self, page: Page | None = None) -> str:
        """Whether the page (default: the tab's) answers a script call: "yes", "hung" (no answer within
        PROBE_SECONDS; e.g. a navigation that never commits, or a hung page) or "error" (e.g. it navigated)."""
        try:
            await asyncio.wait_for((page or self.page).evaluate("document.readyState"), PROBE_SECONDS)
            return "yes"
        except asyncio.TimeoutError:
            return "hung"
        except Exception:
            return "error"

    async def _wait_answer(self, page: Page) -> bool:
        """Wait up to STUCK_SECONDS for the page to answer a script call (a navigation still committing)."""
        until = time.monotonic() + STUCK_SECONDS
        while True:
            answer = await self._answers(page)
            if answer == "yes":
                return True
            if time.monotonic() >= until or page.is_closed():
                return False
            if answer == "error":
                await asyncio.sleep(0.5)

    def _check_alive(self) -> None:
        """Raise when the attempt's tab is provably dead: closed, or the browser's own error page."""
        open_pages = [p for p in self.pages if not p.is_closed()]
        if not open_pages:
            raise ConnectionError("the tab closed")
        if open_pages[-1].url.startswith("chrome-error:"):
            raise ConnectionError(f"the start page did not load ({open_pages[-1].url[:80]})")

    async def _login_pending(self) -> bool:
        """The sign-in was just sent and its form still shows: the post-login page is still loading."""
        if not self.login_at or time.monotonic() - self.login_at[0] > START_SECONDS:
            return False
        if self.page.url != self.login_at[1]:
            return False
        try:
            return bool(await asyncio.wait_for(self.page.locator("input[type=password]:visible").count(), 5))
        except Exception:
            return False

    def _watch(self, page: Page) -> None:
        self.pages.append(page)
        page.on("dialog", lambda dialog: self._owner()._on_dialog(dialog))
        page.on("popup", lambda popup: self._owner()._on_popup(popup))

    def _owner(self) -> "SiteSession":
        """The session a tab reports to: a start contender's tab reports to the session that took it over."""
        return self._adopted_by or self

    def _on_popup(self, popup: Page) -> None:
        self._watch(popup)
        self.events.append(f"a new window opened ({popup.url}); you are now in it, it closes back to the last one")

    async def _on_dialog(self, dialog: Dialog) -> None:
        self.events.append(f"browser {dialog.type} said: {dialog.message!r}; accepted")
        await dialog.accept()

    async def revive(self) -> None:
        """A session whose tabs are all gone (e.g. after a failed start) gets a fresh tab on the site's start page,
        so looking and acting never fail on an empty tab list. While a start runs in another task, this waits for
        it (its tab is the one to use), so a session can be handed out before it is up."""
        if self.starting and _STARTING.get() is not self:
            self.trace.event(self.name, "helper", action="wait_for_start")
            await self.settled.wait()
        if any(not page.is_closed() for page in self.pages):
            return
        page = await self.context.new_page()
        self._watch(page)
        self.events.append("the tab was gone; opened the website again")
        self.trace.event(self.name, "helper", action="revive")
        await self._goto(self.site["url"])

    async def _goto(self, url: str) -> None:
        """Open `url` in the tab and settle: at most GOTO_SECONDS plus SETTLE_SECONDS; slow ones are traced."""
        began = time.monotonic()
        try:
            await self.page.goto(url, wait_until="domcontentloaded", timeout=GOTO_SECONDS * 1000)
        except Exception as error:  # a slow load event still leaves a usable page
            first = str(error).splitlines()[0][:160]
            self.events.append(f"navigation was slow or failed: {first}")
            self.trace.event(self.name, "slow_page", phase="goto", url=url[:120],
                             seconds=round(time.monotonic() - began, 1), error=first)
        loaded = time.monotonic()
        await self.settle()
        if time.monotonic() - began > SLOW_PAGE:
            self.trace.event(self.name, "slow_page", phase="done", url=url[:120],
                             goto=round(loaded - began, 1), settle=round(time.monotonic() - loaded, 1))

    async def settle(self) -> None:
        """Let the page finish and run the generic helpers, but never longer than SETTLE_SECONDS: a click that never
        returns (seen on a cookie notice) must not block the tab for minutes. A page that answers no script call
        any more is opened again (reopen)."""
        alive = True
        try:
            alive = await asyncio.wait_for(self._settle_fresh(), SETTLE_SECONDS)
        except asyncio.TimeoutError:
            self.events.append("the page kept loading; continuing with what it shows")
            self.trace.event(self.name, "helper_error", helper="settle", error=f"timeout after {SETTLE_SECONDS} s")
            alive = await self._answers() != "hung"
        if not alive and not self.starting:
            await self.reopen("the page answers no script call")

    async def _settle_fresh(self) -> bool:
        self.logins = 0  # a timeout later in the run may need a fresh sign-in
        return await self._settle()

    async def reopen(self, why: str) -> bool:
        """
        Give up a tab whose page stopped answering (run ec4e: the bid form hung for 8 minutes and every call into
        it waited out its timeout). The same URL opens in a new tab of the same context first: the site's session,
        and with it a server-side wizard's state, lives in the context's cookies. When that page does not answer
        either, the site starts again in a fresh context (signed in anew; what the old session held is gone, which
        `restarts` tells). True when a page answers again.
        """
        url = self.page.url if any(not p.is_closed() for p in self.pages) else self.site["url"]
        if not url.startswith("http"):
            url = self.site["url"]
        self.trace.event(self.name, "helper", action="reopen", why=why, url=url[:120])
        old, self.pages = list(self.pages), []
        for page in old:  # in the background: closing a hung tab may itself take a while
            asyncio.create_task(_close_quietly(page))
        try:
            page = await asyncio.wait_for(self.context.new_page(), STUCK_SECONDS)
            self._watch(page)
            try:
                await page.goto(url, wait_until="domcontentloaded", timeout=GOTO_SECONDS * 1000)
            except Exception:
                pass  # still loading: whether it answers decides
            if await self._wait_answer(page):
                try:
                    await asyncio.wait_for(self._settle(), SETTLE_SECONDS)
                except asyncio.TimeoutError:
                    pass  # it answers; still loading is fine
                self.events.append("the page stopped answering; it was opened again in a new tab (check where the "
                                   "form stands)")
                return True
        except Exception as error:
            self.trace.event(self.name, "helper_error", helper="reopen", error=f"{type(error).__name__}: {error}"[:160])
        self.trace.event(self.name, "helper", action="restart", why="the reopened page does not answer either")
        await self._close_pages()
        self.restarts += 1
        try:
            fresh = await self._fresh_context("restart")
            if fresh is not None:
                self.context, self.scripted = fresh, None
            await self.start(attempts=2, until=time.monotonic() + START_SECONDS)
        except Exception as error:
            self.trace.event(self.name, "helper_error", helper="restart", error=f"{type(error).__name__}: {error}"[:160])
            return False
        self.events.append("the page stopped answering; the website was opened again from its start page and "
                           "signed in anew: steps not yet submitted are gone")
        return True

    async def _settle(self) -> bool:
        page = self.page
        for _ in range(6):
            try:
                await page.wait_for_load_state("domcontentloaded", timeout=15000)
                await page.wait_for_load_state("networkidle", timeout=2500)
            except Exception:
                pass
            if not await self._wait_answer(page):  # its helpers would hang on every page call
                self.trace.event(self.name, "helper_error", helper="settle",
                                 error=f"the page answers no script call ({page.url[:80]})")
                return False
            if (await self._safely(self._login, page) or await self._safely(self._cookies, page)
                    or await self._safely(self._error_page, page) or await self._safely(self._human_check, page)):
                page = self.page
                continue
            break
        await self._collect_closed(page)
        return True

    async def _safely(self, helper, page: Page) -> bool:
        """A helper that fails (a slow page, a detached element) just did nothing; the model sees the page as is. A
        helper never takes longer than HELPER_SECONDS: page calls on a page that stops answering wait for ever."""
        try:
            return await asyncio.wait_for(helper(page), HELPER_SECONDS)
        except Exception as error:
            text = (str(error).splitlines() or [""])[0][:160] or f"{type(error).__name__} after {HELPER_SECONDS} s"
            self.trace.event(self.name, "helper_error", helper=helper.__name__, error=text)
            return False

    async def _login(self, page: Page) -> bool:
        password = page.locator("input[type=password]:visible")
        if not await password.count() or self.logins >= 2:
            return False
        if self.login_at and self.login_at[1] == page.url and time.monotonic() - self.login_at[0] < LOGIN_PATIENCE:
            return False  # sent moments ago and the old page still shows: the post is pending, do not resend it
        self.logins += 1
        form = password.first.locator("xpath=ancestor::form[1]")
        scope = form if await form.count() else page.locator("body")
        user = scope.locator("input:visible:not([type=password]):not([type=hidden]):not([type=checkbox])"
                             ":not([type=radio]):not([type=submit]):not([type=button])")
        if not await user.count():
            return False
        creds = self.site["credentials"]
        await user.first.fill(creds["username"])
        await password.first.fill(creds["password"])
        try:
            await password.first.press("Enter", timeout=5000)
        except Exception:
            pass  # the form was sent; the page is still loading, which settle waits for
        self.login_at = (time.monotonic(), page.url)
        self.events.append("signed in with this run's login")
        self.trace.event(self.name, "helper", action="login", url=page.url)
        await asyncio.sleep(0.3)
        return True

    async def _cookies(self, page: Page) -> bool:
        buttons = page.locator("button:visible, input[type=submit]:visible")
        candidates = []
        for i in range(min(await buttons.count(), 20)):
            button = buttons.nth(i)
            text = (await button.inner_text() if await button.evaluate("e => e.tagName") == "BUTTON"
                    else await button.get_attribute("value")) or ""
            if COOKIE.search(text) and COOKIE_ANSWER.search(text):
                candidates.append((not COOKIE_MINIMAL.search(text), text.strip(), button))
        if not candidates:
            return False
        candidates.sort(key=lambda c: c[0])  # the necessary-only choice first
        _, text, button = candidates[0]
        await button.click()
        self.events.append(f"cookie notice answered with {text!r}")
        self.trace.event(self.name, "helper", action="cookies", choice=text)
        await asyncio.sleep(0.3)
        return True

    async def _human_check(self, page: Page) -> bool:
        done = []
        for frame in page.frames:
            try:
                done += await asyncio.wait_for(frame.evaluate(HUMAN_CHECK_JS), FRAME_SECONDS)
            except Exception:
                continue
        if not done:
            return False
        self.events.append("unlocked a human check (" + ", ".join(sorted(set(done))) + ")")
        self.trace.event(self.name, "helper", action="human_check", done=done)
        await asyncio.sleep(0.4)
        return True

    async def _error_page(self, page: Page) -> bool:
        try:
            body = await page.locator("body").inner_text(timeout=3000)
        except Exception:
            return False
        if len(body) > 1500 or not ERROR_PAGE.search(body):
            return False
        self.events.append("a transient error page showed; reloaded")
        self.trace.event(self.name, "helper", action="reload", url=page.url)
        await asyncio.sleep(1.0)
        try:
            await page.reload(wait_until="domcontentloaded", timeout=30000)
        except Exception:
            pass
        return True

    async def _collect_closed(self, page: Page) -> None:
        for frame in page.frames:
            try:
                closed = await asyncio.wait_for(frame.evaluate("(window.__arClosed || []).splice(0)"),
                                                FRAME_SECONDS)
            except Exception:
                continue
            for title in closed:
                self.events.append(f"closed popup {title!r} with its close button")
                self.trace.event(self.name, "helper", action="close_popup", title=title)

    async def look(self, offset: int = 0, brief: bool = False, fresh: bool = False) -> str:
        """What the model sees: the helpers' events, the tab, then the page text with refs.

        After an action on the same page, only the changed lines are sent when that is much shorter: the model still
        has its latest full view (worker.py keeps it), and unchanged lines keep their refs. Only with `brief` (the
        browser tools, whose result the model gets as is). `fresh` marks a whole view the model now holds (a
        worker's first prompt); other callers (helpers that reshape the text) get it whole and reset the baseline.
        """
        await self.revive()
        page = self.page
        await self._collect_closed(page)
        self.stamp += 1
        if offset == 0:
            try:
                self.view = await observe(page, str(self.stamp))
            except Exception as error:
                await asyncio.sleep(1.0)
                if not self.starting and await self._answers(page) == "hung" and await self.reopen(
                        "the page answers no script call while it is read"):
                    page = self.page
                try:
                    self.view = (await observe(page, str(self.stamp)) if not page.is_closed()
                                 else f"(page error {error})")
                except Exception as again:  # e.g. a script on the page hangs: the tab does not answer at all
                    self.view = f"(the page does not respond: {type(again).__name__} {str(again)[:160]})"
        try:
            title = await asyncio.wait_for(page.title(), FRAME_SECONDS)
        except Exception:
            title = ""
        header = [f"URL: {page.url}", f"Title: {title}"]
        notes = []
        if len(self.pages) > 1:
            notes.append(f"Windows open: {len(self.pages)} (you are in the newest)")
        if offset == 0 and page.url != self.last_url:
            self.last_url = page.url
            self.visits[page.url] = self.visits.get(page.url, 0) + 1
            if self.visits[page.url] >= LOOP_VISITS:  # a loop guard: paging back and forth finds nothing new
                notes.append(f"Note: you have arrived on this page {self.visits[page.url]} times; going back and "
                             f"forth between the same pages shows nothing new. Act on what this page offers (open "
                             f"an entry, its menu or its actions) or take another route.")
        if self.events:
            notes.append("Since your last action: " + "; ".join(self.events))
            self.events.clear()
        key = (page.url, title, self.view)
        if offset == 0 and brief and key == self.shown:
            return "\n".join([*notes, "The page is unchanged since your last action (same text and refs)."])
        if offset == 0:
            self.trace.event(self.name, "view", quiet=True, url=page.url, text=self.view)
            self.seen += "\n" + self.view
            same_page = brief and self.base and self.base[:2] == key[:2] and len(self.view) <= MAX_VIEW
            diff = changes(self.base[2], self.view) if same_page else None
            if diff is not None:
                self.shown = key
                return "\n".join([*notes, "The page changed. Against your latest full view of it, only these parts "
                                   "differ now (- was there, + is new); everything else, refs included, is as there:",
                                   diff])
        text = self.view[offset:offset + MAX_VIEW]
        rest = len(self.view) - offset - len(text)
        if rest > 0:
            text += f"\n[... {rest} more characters: read_more(offset={offset + len(text)})]"
        self.shown = self.base = key if offset == 0 and rest <= 0 and (brief or fresh) else ()
        return "\n".join(header + notes) + "\n\n" + text

    async def act(self, kind: str, ref: str, fn) -> str:
        """Run one action on the element `ref`, settle, and return the new view."""
        async with self.lock:
            await self.revive()
            element = await locate(self.page, ref)
            if element is None:
                return (f"No element {ref} on this page (refs change with every view).\n\n"
                        + await self.look(brief=True))
            started = time.monotonic()
            before = (self.page.url, self.view)
            try:
                await fn(element)
            except Exception as error:
                first = str(error).splitlines()[0][:300]
                self.trace.event(self.name, "action_error", action=kind, ref=ref, error=first)
                return f"{kind} {ref} failed: {first}\n\n" + await self.look(brief=True)
            await asyncio.sleep(0.25)
            await self.settle()
            self.trace.event(self.name, "action", action=kind, ref=ref, seconds=round(time.monotonic() - started, 2))
            view = await self.look(brief=True)
            if (self.page.url, self.view) == before:
                view = (f"Nothing on the page changed after {kind} {ref}. Do not repeat it; check the page for what "
                        f"is still missing (a required field, a checkbox, another button).\n\n") + view
            return view


async def _click(element) -> None:
    try:
        await element.click(timeout=5000)
    except Exception:
        await element.evaluate("e => e.click()")  # covered by a banner or outside the scroll box


@dataclass
class Deps:
    """What a worker's tools reach: its website and the notes it keeps for the orchestrator."""

    session: SiteSession
    notes: dict[str, str] = field(default_factory=dict)
    refused: dict[str, int] = field(default_factory=dict)


async def goto(ctx: RunContext[Deps], url: str) -> str:
    """Open a URL or a path on this website (e.g. a link's target from the page)."""
    session = ctx.deps.session
    await session.revive()
    target = urljoin(session.page.url, url)
    if urlparse(target).netloc != urlparse(session.site["url"]).netloc:
        return f"{target} is not on this website ({session.site['url']}); stay on it."
    async with session.lock:
        await session._goto(target)
        session.trace.event(session.name, "action", action="goto", url=target)
        return await session.look(brief=True)


async def click(ctx: RunContext[Deps], ref: str) -> str:
    """Click the element with this ref (link, button, tab, summary, checkbox)."""
    return await ctx.deps.session.act("click", ref, _click)


async def fill(ctx: RunContext[Deps], ref: str, text: str, submit: bool = False) -> str:
    """Type text into a textbox or textarea (replaces its content), or set a slider to a number.

    submit=true presses Enter afterwards, which runs a search or sends the field's form.
    """
    async def run(element):
        if await element.evaluate("e => e.type") == "range":
            await element.evaluate("(e, v) => { e.value = v; e.dispatchEvent(new Event('input', {bubbles: true}));"
                                   " e.dispatchEvent(new Event('change', {bubbles: true})); }", text)
        else:
            await element.fill(text, timeout=5000)
        if submit:
            await element.press("Enter")
    return await ctx.deps.session.act("fill", ref, run)


LABELS_JS = r"""
e => Array.from(e.options || []).map(o =>
  [o.textContent.replace(/[\u200b\u200c\u200d\u2060\ufeff\u00ad]/g, '').replace(/\s+/g, ' ').trim(), o.value])
"""


def _option_index(choices: list[list[str]], option: str) -> int | None:
    """The option whose visible text (else value) is `option`, ignoring spacing and then case."""
    want = " ".join(option.split())
    for match in (lambda t, v: t == want, lambda t, v: v == option, lambda t, v: t.casefold() == want.casefold()):
        for i, (text, value) in enumerate(choices):
            if match(text, value):
                return i
    return None


def _close_options(texts: list[str], option: str, limit: int = 8) -> list[str]:
    """Options that contain `option`, else any of its words, for a helpful error."""
    want = option.casefold().strip()
    hits = [t for t in texts if want and want in t.casefold()]
    if not hits:
        words = [w for w in want.replace(",", " ").split() if len(w) > 1]
        hits = [t for t in texts if any(w in t.casefold() for w in words)]
    return hits[:limit]


async def select(ctx: RunContext[Deps], ref: str, option: str) -> str:
    """Choose an option of a select by its visible text."""
    async def run(element):
        choices = await element.evaluate(LABELS_JS)
        index = _option_index(choices, option)
        if index is None:
            texts = [text for text, _ in choices]
            close = _close_options(texts, option)
            hint = f"options like it: {' | '.join(close)}" if close else f"options({ref}, contains) searches them"
            raise ValueError(f"no option {option!r} among {len(texts)}; {hint}")
        await element.select_option(index=index, timeout=5000)
    return await ctx.deps.session.act("select", ref, run)


async def options(ctx: RunContext[Deps], ref: str, contains: str = "") -> str:
    """List the options of a select (views shorten long lists), or only those whose text contains `contains`."""
    session = ctx.deps.session
    async with session.lock:
        found = await select_options(session.page, ref, contains)
    if found is None:
        return f"No select {ref} on this page (refs change with every view)."
    total, hits = found
    which = f" containing {contains!r}" if contains else ""
    text = f"{len(hits)} of {total} options of {ref}{which}:\n" + "\n".join(hits[:300])
    if len(hits) > 300:
        text += f"\n... {len(hits) - 300} more; narrow with contains"
    session.seen += "\n" + text
    return text


async def check(ctx: RunContext[Deps], ref: str, checked: bool = True) -> str:
    """Tick (checked=true) or untick a checkbox or radio button."""
    async def run(element):
        try:
            await element.set_checked(checked, timeout=5000)
        except Exception:
            await element.evaluate("(e, c) => { if (e.checked !== c) e.click(); }", checked)
    return await ctx.deps.session.act("check", ref, run)


async def back(ctx: RunContext[Deps], reason: str = "") -> str:
    """Go back to the previous page."""
    session = ctx.deps.session
    async with session.lock:
        try:
            await session.page.go_back(wait_until="domcontentloaded", timeout=15000)
        except Exception:
            pass
        await session.settle()
        return await session.look(brief=True)


async def read_more(ctx: RunContext[Deps], offset: int) -> str:
    """Show the rest of a long page from the offset the view gave."""
    return await ctx.deps.session.look(offset)


# A run of value characters; those with a digit are values. (The former single pattern, [..]*\d[..]*, retried
# every start of a long run without a digit: quadratic, minutes on one long token.)
VALUE_RUN = re.compile(r"[\w/.:,+-]+")
DIGIT = re.compile(r"\d")


def unseen_values(text: str, seen: str) -> list[str]:
    """The values in `text` (anything with a digit: numbers, references, dates) that `seen` does not contain."""
    missing = []  # a value holds no whitespace, so searching `seen` as is matches its whitespace-normalised form
    for token in VALUE_RUN.findall(text):
        if not DIGIT.search(token):
            continue
        token = token.strip(".,:;/-+")
        if token and token not in seen and token not in missing:
            missing.append(token)
    return missing


async def note(ctx: RunContext[Deps], key: str, value: str) -> str:
    """Record a fact you can see on the current page (copy values exactly), so it survives if you run out of time."""
    missing = unseen_values(value, ctx.deps.session.seen)
    if missing:
        ctx.deps.session.trace.event(ctx.deps.session.name, "note_refused", key=key, missing=missing[:10])
        ctx.deps.refused[key] = ctx.deps.refused.get(key, 0) + 1
        if ctx.deps.refused[key] > 2:
            return (f"Not noted, again. Stop trying to note {key!r}; continue with your goal from what the current "
                    f"page shows.")
        return (f"Not noted: {', '.join(missing[:10])} appear on no page you have seen. Note only values copied "
                f"from a page; open the page again if you need to check.")
    ctx.deps.notes[key] = value
    ctx.deps.session.trace.event(ctx.deps.session.name, "note", key=key, value=value)
    return f"noted {key}"


TOOLS = [goto, click, fill, select, options, check, back, read_more, note]

